$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$modulePath = Join-Path $pkg "ahos\autonomous_company.py"
$testPath = Join-Path $pkg "tests\test_autonomous_company.py"
$backlogPath = Join-Path $pkg "AHOS_BACKLOG.json"
$python = Join-Path $root ".venv\Scripts\python.exe"

if (-not (Test-Path $python)) { throw "Python venv not found." }
if (-not (Test-Path $backlogPath)) { throw "AHOS backlog not found." }

Write-Host "=== AHOS-035 AUTONOMOUS MISSION QUEUE + COMPANY LOOP ==="
Write-Host "This step is LOCAL ONLY."
Write-Host "OpenAI calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host "No messages, publishing, payments, deployment, or external business actions."
Write-Host ""

[IO.File]::WriteAllBytes(
    $modulePath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $testPath,
    [Convert]::FromBase64String("")
)

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
if (-not ($b.tasks | Where-Object { $_.id -eq "AHOS-035" })) {
    $b.tasks += [pscustomobject]@{
        id = "AHOS-035"
        title = "Add persistent autonomous mission queue and company loop"
        status = "pending"
        risk = "low"
        authority = "B"
        requires_owner_approval = $false
        task = "Add a local SQLite-backed persistent mission queue and autonomous company loop with atomic leases, bounded retries, stale-lease recovery, blocked-mission fail-closed behavior, result audit persistence, run-once, run-until-idle, and continuous polling primitives. No AI or external actions in this step."
    }
}
[IO.File]::WriteAllText(
    $backlogPath,
    ($b | ConvertTo-Json -Depth 12),
    (New-Object System.Text.UTF8Encoding($false))
)

Write-Host "Running full AHOS test suite locally..."
$oldPythonPath = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg
    & $python -m pytest -q
    $testExit = $LASTEXITCODE
} finally {
    Pop-Location
    $env:PYTHONPATH = $oldPythonPath
}
if ($testExit -ne 0) {
    throw "AHOS-035 tests failed. Nothing was pushed."
}

# Local proof: persist 3 missions, let one company loop consume them, reopen DB.
$proofDb = Join-Path $pkg "runtime\ahos035-proof.db"
if (Test-Path $proofDb) { Remove-Item $proofDb -Force }

$proof = @'
from pathlib import Path
import json

from ahos.autonomous_company import CompanyLoop, PersistentMissionQueue
from ahos.mission_orchestrator import MissionResult, MissionStatus

db = Path(r"__PROOF_DB__")
queue = PersistentMissionQueue(db)

for i in range(1, 4):
    queue.enqueue(
        mission_id=f"AHOS-035-proof-{i}",
        objective=f"Local autonomous proof mission {i}",
        primary_department="software",
    )

def executor(mission):
    return MissionResult(
        mission_id=mission.mission_id,
        objective=mission.objective,
        manager_id="mgr-software-01",
        status=MissionStatus.COMPLETED,
        steps=(),
        reason="local autonomous proof completed",
    )

processed = CompanyLoop(
    queue=queue,
    executor=executor,
    owner="AHOS-035-PROOF-LOOP",
).run_until_idle()

reopened = PersistentMissionQueue(db)
rows = reopened.list()

print("PROCESSED:", len(processed))
print("PERSISTED:", len(rows))
print("STATUSES:", [row.status.value for row in rows])
print("ATTEMPTS:", [row.attempts for row in rows])

assert len(processed) == 3
assert len(rows) == 3
assert all(row.status.value == "completed" for row in rows)
assert all(row.attempts == 1 for row in rows)
print("AHOS-035 LOCAL AUTONOMOUS LOOP PROOF: PASS")
'@
$proof = $proof.Replace("__PROOF_DB__", $proofDb.Replace("\","\\"))

Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg
    $proof | & $python -
    $proofExit = $LASTEXITCODE
} finally {
    Pop-Location
    $env:PYTHONPATH = $oldPythonPath
}
if ($proofExit -ne 0) {
    throw "AHOS-035 local queue proof failed. Nothing was pushed."
}

# Do not commit the proof DB.
Remove-Item $proofDb -Force -ErrorAction SilentlyContinue

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
$t = $b.tasks | Where-Object { $_.id -eq "AHOS-035" } | Select-Object -First 1
$t.status = "completed"
if ($t.PSObject.Properties.Name -contains "completed_at") {
    $t.completed_at = [DateTime]::UtcNow.ToString("o")
} else {
    $t | Add-Member -NotePropertyName completed_at -NotePropertyValue ([DateTime]::UtcNow.ToString("o"))
}
[IO.File]::WriteAllText(
    $backlogPath,
    ($b | ConvertTo-Json -Depth 12),
    (New-Object System.Text.UTF8Encoding($false))
)

git -C $ws add ahos_core/ahos/autonomous_company.py ahos_core/tests/test_autonomous_company.py ahos_core/AHOS_BACKLOG.json
git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" commit -m "feat(ahos): add autonomous company mission loop"
if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

git -C $ws push origin HEAD
if ($LASTEXITCODE -ne 0) { throw "git push failed." }

Write-Host ""
Write-Host "=== AHOS-035 COMPLETE ==="
Write-Host "Full AHOS tests: PASS"
Write-Host "Persistent SQLite mission queue: PASS"
Write-Host "Atomic mission leasing: PASS"
Write-Host "Stale lease recovery: PASS"
Write-Host "Bounded retries: PASS"
Write-Host "Blocked missions fail closed: PASS"
Write-Host "Audit/result persistence: PASS"
Write-Host "Autonomous run-until-idle loop: PASS"
Write-Host "Git push: PASS"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host ""
Write-Host "NEXT: AHOS-036 will connect this loop to the already-proven AI manager/workers."
